INSERT INTO `page_contents` (`id`, `page_id`, `parent_id`, `type`, `section_title`, `section_name`, `section_content`, `section_file`, `slug`, `created_at`, `updated_at`) VALUES
(2, 1, NULL, 'text', NULL, 'section1-left', '&lt;div class=&quot;hero-content&quot;&gt;\n&lt;div class=&quot;hero-content-wrapper wow fadeInUp   animated&quot; style=&quot;visibility: visible; animation-name: fadeInUp;&quot;&gt;\n&lt;div class=&quot;top-heading-text-banner &quot;&gt;\n&lt;h2 class=&quot;text-uppercase &quot;&gt;Life is beautiful!&amp;nbsp;&lt;/h2&gt;\n\n&lt;h2&gt;... but it has its challenges&lt;/h2&gt;\n&lt;/div&gt;\n\n&lt;h1&gt;For every challenge&lt;br /&gt;\nthere is a solution&lt;/h1&gt;\n\n&lt;h4&gt;Let&amp;#39;s go find it ... together.&lt;/h4&gt;\n\n&lt;div class=&quot;register-link&quot;&gt;&lt;a href=&quot;register_url&quot;&gt;Get Started&lt;/a&gt;&lt;/div&gt;\n&lt;/div&gt;\n&lt;/div&gt;\n', NULL, NULL, NULL, '2022-03-29 18:23:43'),
(3, 1, NULL, 'text', NULL, 'section2', '&lt;div class=&quot;company-info-content&quot;&gt;\n&lt;h2 class=&quot;theme-heading-text home-spanish-langu&quot;&gt;&lt;span&gt;How Can We Help?&lt;/span&gt;&lt;/h2&gt;\n\n&lt;div class=&quot;inner-text-how-help wow fadeInUp animated&quot;&gt;\n&lt;ul&gt;\n	&lt;li&gt;iWILL &amp;lsquo;til i&amp;rsquo;mWELL offers premiere services that are designed to meet your medical and mental health needs.&lt;/li&gt;\n	&lt;li&gt;24X7 Communication with Licensed Physicians &amp;amp; Mental Health Specialists in English and Spanish.&lt;/li&gt;\n	&lt;li&gt;The highest quality care for your body, mind, and soul is offered at a flexible affordable value.&lt;/li&gt;\n&lt;/ul&gt;\n&lt;/div&gt;\n&lt;/div&gt;\n', NULL, NULL, NULL, '2021-12-06 12:15:34'),
(4, 1, NULL, 'text', NULL, 'section3-right', '&lt;div class=&quot;col-md-12 left-text&quot;&gt;\n&lt;h2 class=&quot;text-left theme-heading-text&quot;&gt;Counseling Care Services&lt;/h2&gt;\n\n&lt;div class=&quot;text-center-box&quot;&gt;\n&lt;p class=&quot;text-left &quot;&gt;Need help with anxiety, depression, family issues, or addictions? Speak with a mental health specialist via telephone or video consultation 24 hours/day, 365 days a year.&lt;/p&gt;\n\n&lt;ul class=&quot;text-left medical-ul-box&quot;&gt;\n	&lt;li&gt;Talk about your concerns.&lt;/li&gt;\n	&lt;li&gt;Process your thoughts.&lt;/li&gt;\n	&lt;li&gt;Get immediate mental health care.&lt;/li&gt;\n&lt;/ul&gt;\n\n&lt;div class=&quot;register-link mt-50 d-flex justify-content-start&quot;&gt;&lt;a href=&quot;https://iwilltilimwell.com/behavioral-health&quot;&gt;Talk to a therapist &lt;/a&gt;&lt;/div&gt;\n&lt;/div&gt;\n&lt;/div&gt;\n', NULL, NULL, NULL, '2022-06-10 10:05:07'),
(5, 1, NULL, 'text', NULL, 'section4-left', '&lt;div class=&quot;row&quot;&gt;\n&lt;div class=&quot;col-md-12 left-text&quot;&gt;\n&lt;h2 class=&quot;text-left theme-heading-text&quot;&gt;MEDICAL CARE SERVICES&lt;/h2&gt;\n\n&lt;div class=&quot;text-center-box&quot;&gt;\n&lt;p class=&quot;text-left &quot;&gt;Speak to licensed physicians via telephone or online video consultation in English and Spanish for health information. Unlimited Access 24 hours/day, 365 days a year.&lt;/p&gt;\n\n&lt;ul class=&quot;text-left medical-ul-box&quot;&gt;\n	&lt;li&gt;Diagnose ailments.&lt;/li&gt;\n	&lt;li&gt;Give treatment recommendations.&lt;/li&gt;\n	&lt;li&gt;Can write prescriptions*, if deemed appropriate and necessary.&lt;/li&gt;\n&lt;/ul&gt;\n\n&lt;div class=&quot;register-link mt-50 d-flex justify-content-start&quot;&gt;&lt;a href=&quot;https://iwilltilimwell.com/consultation-type&quot;&gt;Talk to a doctor &lt;/a&gt;&lt;/div&gt;\n&lt;/div&gt;\n&lt;/div&gt;\n&lt;/div&gt;\n', NULL, NULL, NULL, '2022-06-10 10:04:21'),
(6, 1, NULL, 'text', NULL, 'section5', '&lt;div class=&quot;inner-promo-home cust-container&quot;&gt;\n&lt;div class=&quot;row&quot;&gt;\n&lt;div class=&quot;col-lg-3&quot;&gt;\n&lt;div class=&quot;promo-box wow bounceIn&quot; data-wow-delay=&quot;0.3s&quot; style=&quot;visibility: visible; animation-delay: 0.3s; animation-name: bounceIn;&quot;&gt;\n&lt;div class=&quot;promo-icon&quot;&gt;&lt;img src=&quot;https://www.iwilltilimwell.com/images/promo-icon-1.png&quot; /&gt;&lt;/div&gt;\n\n&lt;div class=&quot;promo-box-right&quot;&gt;\n&lt;h2&gt;75%&lt;/h2&gt;\n\n&lt;p&gt;of most practices&lt;br /&gt;\nare closed after 6 pm&lt;/p&gt;\n&lt;/div&gt;\n&lt;/div&gt;\n&lt;/div&gt;\n\n&lt;div class=&quot;col-lg-3&quot;&gt;\n&lt;div class=&quot;promo-box wow bounceIn&quot; data-wow-delay=&quot;0.5s&quot; style=&quot;visibility: visible; animation-delay: 0.5s; animation-name: bounceIn;&quot;&gt;\n&lt;div class=&quot;promo-icon&quot;&gt;&lt;img src=&quot;https://www.iwilltilimwell.com/images/promo-icon-2.png&quot; /&gt;&lt;/div&gt;\n\n&lt;div class=&quot;promo-box-right&quot;&gt;\n&lt;h2&gt;4hrs&lt;/h2&gt;\n\n&lt;p&gt;Average time in the&lt;br /&gt;\nemergency waiting room&lt;/p&gt;\n&lt;/div&gt;\n&lt;/div&gt;\n&lt;/div&gt;\n\n&lt;div class=&quot;col-lg-3&quot;&gt;\n&lt;div class=&quot;promo-box wow bounceIn&quot; data-wow-delay=&quot;0.7s&quot; data-wow-duration=&quot;1s&quot; style=&quot;visibility: visible; animation-duration: 1s; animation-delay: 0.7s; animation-name: bounceIn;&quot;&gt;\n&lt;div class=&quot;promo-icon&quot;&gt;&lt;img src=&quot;https://www.iwilltilimwell.com/images/promo-icon-3.png&quot; /&gt;&lt;/div&gt;\n\n&lt;div class=&quot;promo-box-right&quot;&gt;\n&lt;h2&gt;21&lt;/h2&gt;\n\n&lt;p&gt;Average number of days&lt;br /&gt;\nto schedule Dr. appt.&lt;/p&gt;\n&lt;/div&gt;\n&lt;/div&gt;\n&lt;/div&gt;\n\n&lt;div class=&quot;col-lg-3&quot;&gt;\n&lt;div class=&quot;promo-box wow bounceIn&quot; data-wow-delay=&quot;0.9s&quot; data-wow-duration=&quot;1s&quot; style=&quot;visibility: visible; animation-duration: 1s; animation-delay: 0.9s; animation-name: bounceIn;&quot;&gt;\n&lt;div class=&quot;promo-icon&quot;&gt;&lt;img src=&quot;https://www.iwilltilimwell.com/images/promo-icon-4.png&quot; /&gt;&lt;/div&gt;\n\n&lt;div class=&quot;promo-box-right&quot;&gt;\n&lt;h2&gt;66%&lt;/h2&gt;\n\n&lt;p&gt;of ER visits&lt;br /&gt;\nare non-emergency&lt;/p&gt;\n&lt;/div&gt;\n&lt;/div&gt;\n&lt;/div&gt;\n&lt;/div&gt;\n&lt;/div&gt;\n', NULL, NULL, NULL, '2022-06-22 04:24:12'),
(7, 1, NULL, 'text', NULL, 'section6', '&lt;div class=&quot;company-info-content&quot;&gt;\n&lt;h2 class=&quot;theme-heading-text text-center home-spanish-langu&quot;&gt;&lt;span&gt;How Can We Help?&lt;/span&gt;&lt;/h2&gt;\n\n&lt;p class=&quot;text-center&quot;&gt;Get started with 4 easy steps.&lt;/p&gt;\n&lt;/div&gt;\n', NULL, NULL, NULL, '2022-06-08 12:35:59'),
