INSERT INTO `safety_plans` (`id`, `title`, `description`, `inner_description`, `number`, `type`, `icon`, `created_at`, `updated_at`) VALUES
(1, 'Warning Signs / Triggers', '&lt;p&gt;Tap the row to add warning signs that a crisis may occur&lt;/p&gt;\r\n', '&lt;p&gt;What sort of thoughts, images, moods, situations, or behaviors indicate to you that a crisis may be developing? (Ex. Urges to drink, sleeping more than usual, skipping responsibilities, etc.)&lt;/p&gt;\r\n', NULL, 'plan', 'uploads/safetyplan/safety_1649364616_ico-15.png', '2022-04-08 07:24:17', '2022-05-19 01:54:37'),
(2, 'Coping Strategies', '&lt;p&gt;Tap the row to add coping strategies&lt;/p&gt;\r\n', '&lt;p&gt;What are some things that you can do on your own to help you not act on thoughts/urges to harm yourself? (Ex. television, exercise, games )&lt;/p&gt;\r\n', NULL, 'plan', 'uploads/safetyplan/safety_1649364674_ico-1.png', '2022-04-08 07:44:53', '2022-04-08 16:21:14'),
(3, 'Reasons to live', '&lt;p&gt;Tap the row to to add things that are worth living for&amp;nbsp;&lt;/p&gt;\r\n', '&lt;p&gt;Enter things that are important to you and worth living for:&lt;/p&gt;\r\n', NULL, 'plan', 'uploads/safetyplan/safety_1649364717_ico-7.png', '2022-04-08 07:47:06', '2022-04-08 16:21:57'),
(4, 'Contacts', '&lt;p&gt;Tap the row to add any people, professionals, or other numbers that you can contact during a crisis&lt;/p&gt;\r\n', '&lt;p&gt;Enter the names and numbers of friends, family, professionals, or other resources you can contact during a crisis.&lt;/p&gt;\r\n\r\n&lt;p&gt;Import Contact Information&lt;br /&gt;\r\nName: &amp;hellip;&amp;hellip;&amp;hellip;&amp;hellip;&amp;hellip;..&lt;br /&gt;\r\nPhone#:&amp;hellip;&amp;hellip;&amp;hellip;&amp;hellip;&amp;hellip;&amp;hellip;.&lt;/p&gt;\r\n', NULL, 'plan', 'uploads/safetyplan/safety_1649364763_ico-16.png', '2022-04-08 07:48:57', '2022-05-19 01:58:00'),
(5, 'Healthy Social Settings/Activities', '&lt;p&gt;Tap the row to add places that can distract you&amp;nbsp;&lt;/p&gt;\r\n', '&lt;p&gt;What healthy social settings can help take your mind off things that may be troubling you?&amp;nbsp; (Ex. Local park, Coffee shop visit with family, friends)&lt;/p&gt;\r\n', NULL, 'plan', 'uploads/safetyplan/safety_1649364818_ico-3.png', '2022-04-08 07:53:00', '2022-05-19 01:51:26'),
(6, 'Other', '&lt;p&gt;Tap the row to add any additional notes that could be helpful&lt;/p&gt;\r\n', '&lt;p&gt;Enter any other notes that may be helpful to you during a crisis.&lt;/p&gt;\r\n', NULL, 'plan', 'uploads/safetyplan/safety_1649364876_ico-10.png', '2022-04-08 07:56:42', '2022-04-08 16:24:36'),
(7, 'Overview\r\n', '&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;line-height:150%&quot;&gt;&lt;span style=&quot;font-family:Calibri,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;background:white&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;color:#212121&quot;&gt;If you have&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;background:white&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;depression&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;background:white&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;color:#212121&quot;&gt;, whether it has been diagnosed by a healthcare provider or not, there is a very real risk that at some point in the course of the illness, you may experience&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;background:white&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;thoughts of suicide&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;. &lt;span style=&quot;color:#1f1f1f&quot;&gt;Many people have had suicidal thoughts at some point in their lives, and w&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;background:white&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;color:#212121&quot;&gt;hile the emotional pain that triggers these thoughts may feel overwhelming, it does not mean that you will lose control or act on your thoughts.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n\r\n&lt;p style=&quot;margin-bottom:15px&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;background:white&quot;&gt;&lt;span style=&quot;line-height:21.0pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,&amp;quot;serif&amp;quot;&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;color:#1f1f1f&quot;&gt;Thinking of suicide occurs when the pain you are feeling is exceeding the number of resources you have for coping with that pain. You may think that you have no options left and suicide would be a way to escape this intense emotional pain.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n\r\n&lt;p style=&quot;margin-bottom:15px&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;background:white&quot;&gt;&lt;span style=&quot;line-height:21.0pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,&amp;quot;serif&amp;quot;&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;color:#1f1f1f&quot;&gt;Suicide is a PERMANENT SOLUTION to a TEMPORARY PROBLEM.&amp;nbsp; This pain may seem overwhelming and permanent, but with time, support, and professional help, you can overcome your problems and the pain, and the suicidal feelings will pass.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n\r\n&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;line-height:150%&quot;&gt;&lt;span style=&quot;font-family:Calibri,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;color:#1f1f1f&quot;&gt;To help your suicidal feelings pass, as a good clinician, we have designed a Safety Plan to help you.&amp;nbsp; &lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;background:white&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;color:#212121&quot;&gt;A suicide safety plan is a written set of instructions that you create for yourself as a contingency plan should you begin to experience&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;background:white&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;thoughts about harming yourself.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;background:white&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;color:#212121&quot;&gt; &amp;nbsp;It contains a series of gradually escalating steps that you should follow, proceeding from one step to the next, until you are safe.&amp;nbsp; This will help you to cope with your bad feelings until your circumstances change.&amp;nbsp; &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n\r\n&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;line-height:150%&quot;&gt;&lt;span style=&quot;font-family:Calibri,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;background:white&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;color:#212121&quot;&gt;Try to create your Safety Plan while you are feeling well and can think clearly, rather than waiting until you are actively suicidal. &amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;color:#1f1f1f&quot;&gt;If following the Safety Plan is not enough to alleviate your pain, please call 911, one of our counselors, a crisis line from our Crisis tab or go to your local emergency center. &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n', '', NULL, 'guide', 'uploads/safetyplan/safety_1649365019_ico-12.png', '2022-04-08 08:09:32', '2022-11-14 18:52:50'),
(8, 'Coping\r\n', '&lt;p align=&quot;center&quot; style=&quot;margin-bottom:15px; text-align:center&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;background:white&quot;&gt;&lt;span style=&quot;line-height:21.0pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;b&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;color:#1f1f1f&quot;&gt;Stay in Touch - Do Not Isolate or Withdraw&lt;/span&gt;&lt;/span&gt;&lt;/b&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n\r\n&lt;p style=&quot;margin-bottom:15px&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;background:white&quot;&gt;&lt;span style=&quot;line-height:21.0pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;color:#1f1f1f&quot;&gt;Don&amp;rsquo;t withdraw from life.&amp;nbsp; Socialize and do things that make you happy.&amp;nbsp; Keep in touch with loved ones.&amp;nbsp; Talk with someone when you feel low.&amp;nbsp; &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n\r\n&lt;p align=&quot;center&quot; style=&quot;margin-bottom:15px; text-align:center&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;background:white&quot;&gt;&lt;span style=&quot;line-height:21.0pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;b&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;color:#1f1f1f&quot;&gt;Get Active&lt;/span&gt;&lt;/span&gt;&lt;/b&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n\r\n&lt;p style=&quot;margin-bottom:15px&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;background:white&quot;&gt;&lt;span style=&quot;line-height:21.0pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;color:#1f1f1f&quot;&gt;Exercise.&amp;nbsp; Evidence shows that exercise can release endorphins and help lift your mood.&amp;nbsp; If you haven&amp;rsquo;t exercised in a while, start with a slow or brisk walk.&amp;nbsp; &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n\r\n&lt;p align=&quot;center&quot; style=&quot;margin-bottom:15px; text-align:center&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;background:white&quot;&gt;&lt;span style=&quot;line-height:21.0pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;b&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;color:#1f1f1f&quot;&gt;Don&amp;rsquo;t Drink too Much Alcohol&lt;/span&gt;&lt;/span&gt;&lt;/b&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n\r\n&lt;p style=&quot;margin-bottom:15px&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;background:white&quot;&gt;&lt;span style=&quot;line-height:21.0pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;color:#1f1f1f&quot;&gt;For some, alcohol can become a problem.&amp;nbsp; Alcohol won&amp;rsquo;t help you solve your problems.&amp;nbsp; Alcohol is a depressant and can make you feel worse.&amp;nbsp; &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n\r\n&lt;p align=&quot;center&quot; style=&quot;margin-bottom:15px; text-align:center&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;background:white&quot;&gt;&lt;span style=&quot;line-height:21.0pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;b&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;color:#1f1f1f&quot;&gt;Practice Relaxation&lt;/span&gt;&lt;/span&gt;&lt;/b&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n\r\n&lt;p style=&quot;margin-bottom:15px&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;background:white&quot;&gt;&lt;span style=&quot;line-height:21.0pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;color:#1f1f1f&quot;&gt;Practicing mindfulness meditation for relaxation is a way of training your mind to slow down and to let go of anything that might be causing you harm.&amp;nbsp; &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n\r\n&lt;p align=&quot;center&quot; style=&quot;margin-bottom:15px; text-align:center&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;background:white&quot;&gt;&lt;span style=&quot;line-height:21.0pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;b&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;color:#1f1f1f&quot;&gt;Visualize a Happy Memory&lt;/span&gt;&lt;/span&gt;&lt;/b&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n\r\n&lt;p style=&quot;margin-bottom:15px&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;background:white&quot;&gt;&lt;span style=&quot;line-height:21.0pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;color:#1f1f1f&quot;&gt;Before you go to a dark place and let negative feelings overcome you, shut your eyes and visualize a happy memory.&amp;nbsp; &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n\r\n&lt;p align=&quot;center&quot; style=&quot;margin-bottom:15px; text-align:center&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;background:white&quot;&gt;&lt;span style=&quot;line-height:21.0pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;b&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;color:#1f1f1f&quot;&gt;Eat Healthy Foods&lt;/span&gt;&lt;/span&gt;&lt;/b&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n\r\n&lt;p style=&quot;margin-bottom:15px&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;background:white&quot;&gt;&lt;span style=&quot;line-height:21.0pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;color:#1f1f1f&quot;&gt;A healthy diet that incorporates vegetables, fruits, whole grains and fish may be linked to good mental health.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n\r\n&lt;p align=&quot;center&quot; style=&quot;margin-bottom:15px; text-align:center&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;background:white&quot;&gt;&lt;span style=&quot;line-height:21.0pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;b&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;color:#1f1f1f&quot;&gt;Follow Your Safety Plan and Seek Help&lt;/span&gt;&lt;/span&gt;&lt;/b&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n\r\n&lt;p style=&quot;margin-bottom:15px&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;background:white&quot;&gt;&lt;span style=&quot;line-height:21.0pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;&lt;span style=&quot;color:#1f1f1f&quot;&gt;Call iWILL &amp;lsquo;til i&amp;rsquo;mWELL Counselors&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n', '', NULL, 'guide', 'uploads/safetyplan/safety_1649365036_ico-17.png', '2022-04-08 08:11:03', '2022-11-14 18:52:15'),
(9, 'Recovering\r\n', '&lt;div class=&quot;guide-list-inside&quot;&gt;\r\n&lt;h4&gt;Reach out for help&lt;/h4&gt;\r\n\r\n&lt;p&gt;Get professional support by talking to your doctor or by going to other resources available online. Many times, suicidal thoughts are caused by clinical depression or other mental illnesses. Mental health professionals such as a therapist or a psychiatrist can help you overcome these problems. In addition, there may be support groups in the area that can help you share your experiences and listen to the experiences of others in an understanding manner.&lt;/p&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div class=&quot;guide-list-inside&quot;&gt;\r\n&lt;h4&gt;Make a schedule&lt;/h4&gt;\r\n\r\n&lt;p&gt;Follow a routine for yourself every day and stick to it as closely as possible. For example, wake up at a regular time, sleep at a regular time, and have regular planned activities in your day such as exercising or showering.&lt;/p&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div class=&quot;guide-list-inside&quot;&gt;\r\n&lt;h4&gt;Take care of yourself&lt;/h4&gt;\r\n\r\n&lt;p&gt;It&amp;#39;s important to take good care of yourself. Strategies that have been shown to improve your mood are exercising, getting proper nutrition, sleeping well, getting more sunlight, and forming supportive relationships.&lt;/p&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div class=&quot;guide-list-inside&quot;&gt;\r\n&lt;h4&gt;Identify signs of suicidal thoughts&lt;/h4&gt;\r\n\r\n&lt;p&gt;In the Safety Plan you can identify warning signs of a suicidal crisis, such as certain situations, places, or people. Try to find ways to avoid these triggers. mental health professionals such as therapist or a psychiatrist can help you overcome these problems. In addition, there may be support groups in the area that can help you share your experiences and listen to the experiences of others in an understanding manner.&lt;/p&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div class=&quot;guide-list-inside&quot;&gt;\r\n&lt;h4&gt;Make a schedule&lt;/h4&gt;\r\n\r\n&lt;p&gt;Follow a routine for yourself every day and stick to it as closely as possible. For example, wake up at a regular time, sleep at a regular time, and have regular planned activities in your day such as exercising or showering.&lt;/p&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div class=&quot;guide-list-inside&quot;&gt;\r\n&lt;h4&gt;Take care of yourself&lt;/h4&gt;\r\n\r\n&lt;p&gt;It&amp;#39;s important to take good care of yourself. Strategies that have been shown to improve your mood are exercising, getting proper nutrition, sleeping well, getting more sunlight, and forming supportive relationships.&lt;/p&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div class=&quot;guide-list-inside&quot;&gt;\r\n&lt;h4&gt;Identify signs of suicidal thoughts&lt;/h4&gt;\r\n\r\n&lt;p&gt;Identify signs of suicidal thoughts&lt;/p&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div class=&quot;guide-list-inside&quot;&gt;\r\n&lt;h4&gt;Identify signs of suicidal thoughts&lt;/h4&gt;\r\n\r\n&lt;ul&gt;\r\n	&lt;li&gt;Being alone&lt;/li&gt;\r\n	&lt;li&gt;Alcohol and drugs&lt;/li&gt;\r\n	&lt;li&gt;Doing things that make you feel worse&lt;/li&gt;\r\n	&lt;li&gt;Ruminating about suicide&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;/div&gt;\r\n', '', NULL, 'guide', 'uploads/safetyplan/safety_1649365057_ico-11.png', '2022-04-08 08:12:17', '2022-11-14 18:52:07'),
(10, 'Call 911 for an Emergency', '', '', 'tel:911', 'crisis', 'uploads/safetyplan/safety_1649365294_ico-call.png', '2022-04-08 08:17:03', '2022-07-12 11:42:40'),
(11, 'Call 988 for a Mental Health Emergency', '', '', 'tel:988', 'crisis', 'uploads/safetyplan/safety_1649365280_ico-call.png', '2022-04-08 08:17:36', '2022-07-12 11:42:30'),
(12, 'Safety Plans\r\n', '&lt;p&gt;Suicidal thoughts can seem like they will last forever - but for many, these thoughts and feelings pass. Having a plan in place that can help guide you through difficult moments can make a difference and keep you safe. Ideally, such a plan is developed jointly with your counselor or therapist.&lt;/p&gt;\r\n\r\n&lt;p&gt;It can also be developed with a crisis line counselor who can help you write down actions to take and people to contact in order to feel safe from suicide. In general, a safety plan is designed so that you can start at step one and continue through the steps until you feel safe. When you have thoughts of suicide, refer to your safety plan. The following are essential elements to explore and include in the development of your safety plan: Recognize warning signs What sorts of thoughts, images, moods, situations, and behaviors indicate to you that a crisis may be developing? Write these down in your own words. Use your own coping strategies without contacting another person: What are some things that you can do on your own to help you not act on thoughts/urges to harm yourself?&lt;/p&gt;\r\n\r\n&lt;p&gt;Remind yourself of your reasons for living: What are things that are most important to you? Reach out. Add family members, friends, mental health professionals, local agencies, or anybody else who you can call for support or to help resolve find a place with others who may offer support as well as distraction from the crisis Make a list of healthy social settings that may help take your mind off things.&lt;/p&gt;\r\n', '', NULL, 'guide', 'uploads/safetyplan/safety_1649365082_ico-12.png', '2022-04-08 08:17:41', '2022-11-14 18:51:28'),
(13, 'Find Urgent Care near me', '', '', 'https://www.google.com/maps/search/find+urgent +care+near+me', 'crisis', 'uploads/safetyplan/safety_1661498414_care.png', '2022-04-08 08:19:01', '2022-08-26 14:20:14'),
(14, 'Find Emergency Room near me', '', '', 'https://www.google.com/maps/search/find+emergency+near+me', 'crisis', 'uploads/safetyplan/safety_1661498550_emergency-room-icon.png', '2022-04-08 08:20:03', '2022-08-26 14:22:30'),
(15, 'Suicide Prevention\r\n', '&lt;p&gt;&amp;nbsp;&lt;/p&gt;\r\n\r\n&lt;div class=&quot;guide-list-inside&quot;&gt;\r\n&lt;h4&gt;Introduction&lt;/h4&gt;\r\n\r\n&lt;p&gt;People dealing with suicidal thoughts don&amp;#39;t necessarily want to die - they just want to stop the pain. Please take any signs of suicidal thought seriously. In this guide we will cover the warning signs of suicide, how to talk to a suicidal person about suicide, responding to a suicidal crisis, and supporting them during recovery.&lt;/p&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div class=&quot;guide-list-inside&quot;&gt;\r\n&lt;h4&gt;Warning signs of suicide&lt;/h4&gt;\r\n\r\n&lt;p&gt;It is important to recognize the warning signs of suicide and to take them seriously.&lt;/p&gt;\r\n\r\n&lt;p&gt;suicidal thoughts, varying reactions to different antidepressants means that for some, the first time on antidepressants or changes in antidepressant type / dose increase the risk of suicide. It is critical to monitor someone because the risk of suicide&lt;/p&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div class=&quot;guide-list-inside&quot;&gt;\r\n&lt;h4&gt;Warning Signs:&lt;/h4&gt;\r\n\r\n&lt;ul&gt;\r\n	&lt;li&gt;Talking about wanting to die or to kill oneself.&lt;/li&gt;\r\n	&lt;li&gt;Looking for a way to kill oneself, such as searching online or buying a gun.&lt;/li&gt;\r\n	&lt;li&gt;Talking about feeling hopeless or having no reason to live.&lt;/li&gt;\r\n	&lt;li&gt;Talking about feeling trapped or in unbearable pain.&lt;/li&gt;\r\n	&lt;li&gt;Talking achat about burden to adhere.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div class=&quot;guide-list-inside&quot;&gt;\r\n&lt;h4&gt;Talking to a suicidal person&lt;/h4&gt;\r\n\r\n&lt;p&gt;It is important to recognize the warning signs of suicide and to take them seriously.&lt;/p&gt;\r\n\r\n&lt;p&gt;If you think a friend or family member is considering suicide, you might be afraid to bring up the subject. However, talking openly about suicidal thoughts and feelings can save a life. The easiest way to start the conversation is simply to ask: Are you having thoughts of suicide?&lt;/p&gt;\r\n\r\n&lt;ul&gt;\r\n	&lt;li&gt;Be direct. Talk openly and matter-of-factly about suicide.&lt;/li&gt;\r\n	&lt;li&gt;Be willing to listen. Allow expressions of feelings. Accept the feelings.&lt;/li&gt;\r\n	&lt;li&gt;Be non-judgmental. Don&amp;#39;t debate whether suicide is right or wrong, or whether feelings are good or bad. Don&amp;#39;t lecture on the value of life.&lt;/li&gt;\r\n	&lt;li&gt;Get involved. Become available. Show interest and support.&lt;/li&gt;\r\n	&lt;li&gt;Don&amp;#39;t dare him or her to do it.&lt;/li&gt;\r\n	&lt;li&gt;Don&amp;#39;t act shocked. This will put distance between you.&lt;/li&gt;\r\n	&lt;li&gt;Don&amp;#39;t be sworn to secrecy. Seek support.&lt;/li&gt;\r\n	&lt;li&gt;Offer hope that alternatives are available but do not offer glib reassurance.&lt;/li&gt;\r\n	&lt;li&gt;Take action. Remove means, such as guns or stockpiled pills.&lt;/li&gt;\r\n	&lt;li&gt;Get help from persons or agencies specializing in crisis intervention and suicide prevention.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div class=&quot;guide-list-inside&quot;&gt;\r\n&lt;h4&gt;Respond quickly in a crisis&lt;/h4&gt;\r\n\r\n&lt;p&gt;When somebody tells you they are thinking about suicide, you can start with evaluating the level of suicide risk that the person is in.&lt;/p&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div class=&quot;guide-list-inside&quot;&gt;\r\n&lt;h4&gt;Level of suicide risk&lt;/h4&gt;\r\n\r\n&lt;ul&gt;\r\n	&lt;li&gt;&lt;strong&gt;Low -&lt;/strong&gt; thoughts of suicide, but no plan or intent&lt;/li&gt;\r\n	&lt;li&gt;&lt;strong&gt;Medium -&lt;/strong&gt; thoughts of suicide with vague plan, but no suicidal actions&lt;/li&gt;\r\n	&lt;li&gt;&lt;strong&gt;High -&lt;/strong&gt; thoughts of suicide with specific plan&lt;/li&gt;\r\n	&lt;li&gt;&lt;strong&gt;Very high -&lt;/strong&gt; thoughts of suicide with specific plan&lt;/li&gt;\r\n&lt;/ul&gt;\r\n\r\n&lt;p&gt;If a suicide attempt seems imminent, call a local crisis center, dial 911, or take the person to an emergency room. Remove guns, drugs, knives, and other potentially lethal objects from the vicinity but do not, under any circumstances, leave a suicidal person alone.&lt;/p&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;div class=&quot;guide-list-inside&quot;&gt;\r\n&lt;h4&gt;Support during recovery&lt;/h4&gt;\r\n\r\n&lt;p&gt;Remove potential means of suicide - Remove knives, guns, and other potential lethal objects from the suicidal person. If he or she is likely to overdose on pills, then keep medications with you and give them out only as necessary to follow the prescription.&lt;/p&gt;\r\n\r\n&lt;p&gt;Get them professional help - Encourage the person to seek a mental health professional, be it a doctor or therapist. You can call a crisis line for help and guidance, even if you yourself are not suicidal.&lt;/p&gt;\r\n\r\n&lt;p&gt;Support them - Ask the person every once in a while how he or she is feeling so that if the person is going through another suicidal crisis, you can ensure they are not alone. Encourage the person to reach out to you if they are feeling acutely suicidal.&lt;/p&gt;\r\n\r\n&lt;p&gt;Take care of yourself - It can be emotionally difficult to support a person for an extended period of time. It is important for you to make sure your own health and happiness are solid. While you cannot simply control the suicidal person and make them better, you can control how well you take care of yourself.&lt;/p&gt;\r\n&lt;/div&gt;\r\n', '', NULL, 'guide', 'uploads/safetyplan/safety_1649365103_ico-5.png', '2022-04-08 08:20:47', '2022-11-14 18:51:56'),
(16, 'Making Environment Safe\r\n', '&lt;p&gt;It is critical to make your environment safe by removing things you could use to hurt yourself. Either remove them yourself or talk to a trusted friend or family member and have them remove objects such as guns, knives, razors, or pills. If you need pills regularly, your trusted friend or family member can give you the pills on an as-needed basis according to the prescription. If you have a specific plan in place, make sure to tell your trusted friend or family member about the plan so they can ensure your safety.&lt;/p&gt;\r\n', '', NULL, 'guide', 'uploads/safetyplan/safety_1649365129_ico-8.png', '2022-04-08 08:21:53', '2022-11-14 18:51:48'),
(17, 'Resources\r\n', '&lt;div class=&quot;resources-content-box&quot;&gt;&lt;strong&gt;Helpguide -&lt;/strong&gt; Dealing with Suicide&lt;strong&gt;Helpguide -&lt;/strong&gt; Helping Someone Who Is Suicidal&lt;strong&gt;Metanoia -&lt;/strong&gt; If you are thinking about suicide&lt;strong&gt;Wikihow -&lt;/strong&gt; How to Cope With Suicidal&lt;/div&gt;\r\n', '', NULL, 'guide', 'uploads/safetyplan/safety_1649365199_ico-2.png', '2022-04-08 08:22:45', '2022-11-14 18:51:38'),
(19, 'Find a Substance Abuse center near me', '', '', 'https://www.google.com/maps/search/Find+a+Substance+abuse+center+near+me', 'crisis', 'uploads/safetyplan/safety_1662722967_text-format.png', '2022-09-09 18:29:27', '2022-09-09 18:29:27'),
(20, '&lt;p&gt;National Suicide Prevention Lifeline &lt;span&gt;( 1-800-273-8255 )&lt;/span&gt;&lt;/p&gt;\r\n', '', '', 'tel:+18002738255', 'crisis', 'uploads/safetyplan/safety_1666855584_Untitled-2.png', '2022-07-01 10:58:13', '2022-11-08 18:26:03'),
(21, '&lt;p&gt;RAINN - Rape and Incest National Hotline &lt;span&gt;( 1-800-656-4673 )&lt;/span&gt;&lt;/p&gt;\r\n', '', '', 'tel:+18006564673', 'crisis', 'uploads/safetyplan/safety_1661498590_rape-icon.png', '2022-07-01 11:44:26', '2022-11-08 18:25:47'),
(22, '&lt;p&gt;The Trevor Project - Crisis Intervention to LGBTQ &lt;span&gt;( 1-866-488-7386 )&lt;/span&gt;&lt;/p&gt;\r\n', '', '', 'tel:+18664887386', 'crisis', 'uploads/safetyplan/safety_1661498572_project-icon.png', '2022-07-01 11:45:38', '2022-11-08 18:25:36'),
(23, '&lt;p&gt;Text Crisis Text Line ( Text &amp;quot;Start&amp;quot; to 741-741) \r\n&lt;p&gt;(The Trevor Project Text ( LGBTQ ) &amp;quot;Start&amp;quot; to 678-678 )&lt;/p&gt;\r\n', '', '', 'javascript', 'crisis', 'uploads/safetyplan/safety_1661498623_text-format.png', '2022-07-01 10:56:15', '2022-11-08 18:25:19');
